@block RotaryCtrlLP begin
    # 1 kHz firmware of the rotary pendulum on the FLEXIBLE arm (generated by design/flex_build.py from
    # design.json and flex_design.json). RotaryCtrl with the feedback through a second-order low-pass:
    #
    #   phase 0  t < t_on            motor voltage 0 (hanging, at rest)
    #   phase 1  swing-up            w = -K(t) (x - x*(t)) - Kf(t) xf,   u = u*(t) + xf1
    #   phase 2  balance (latched)   w = -Klqr x - Kf xf,                u = xf1
    #   filter (every tick)           xf <- Af xf + Bf w
    #
    # The filter is 1/(s^2/wc^2 + 2 zeta s/wc + 1), wc = 2 pi 12 Hz, zeta 0.7071, sampled with a
    # zero-order hold; xf = (y, y') is its state, y the feedback voltage. The gains K, Kf are the LQR and
    # the discrete TVLQR of the rigid sampled model WITH the filter in the loop (same weights as RotaryCtrl),
    # so the loop rolls off above about 12 Hz and leaves the arm mode (about 70 Hz) alone. The nominal
    # x*, u* is the rigid swing-up of RotaryCtrl, unchanged. A table row is [x*_1 .. x*_8, u*, K_1 .. K_8,
    # Kf_1, Kf_2]; the catch rule reads the x block of the LQR cost-to-go.
    @constants NT::Int = 401
    @inputs begin
        q1::Real
        q2::Real
        q3::Real
        q4::Real
        w1::Real
        w2::Real
        w3::Real
        w4::Real
        tm::Real
    end
    @outputs begin
        u::Real = 0.0, [unit = "V"]
        phase::Real = 0.0
        vcost::Real = 0.0
        ufb::Real = 0.0, [unit = "V", description = "Filtered feedback voltage (xf1)"]
    end
